const Avatar = ({ user }: { user: User }) => {
  const initials = `${user.first_name?.[0] || ""}${user.last_name?.[0] || ""}`.toUpperCase();

  return (
    <div
      style={{
        width: 40,
        height: 40,
        borderRadius: "50%",
        overflow: "hidden",
        background: "#E2E8F0",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontWeight: 700,
        fontSize: 14,
        color: "#334155",
        flexShrink: 0,
      }}
    >
      {user.image_url ? (
        <img
          src={user.image_url}
          alt={user.name}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
          onError={(e) => {
            e.currentTarget.style.display = "none";
          }}
        />
      ) : (
        initials || "U"
      )}
    </div>
  );
};
